def _ansi_box(title, url, accent, icon, description, info_lines):
    import qrcode
    import shutil
    term_width = shutil.get_terminal_size(fallback=(100, 40)).columns
    box_width = max(42, min(60, (term_width - 4) // 2))
    if box_width > term_width - 4:
        box_width = max(30, term_width - 4)
    qr = qrcode.QRCode(error_correction=qrcode.constants.ERROR_CORRECT_M, box_size=1, border=4)
    qr.add_data(url)
    qr.make(fit=True)
    matrix = qr.get_matrix()
    if len(matrix) % 2:
        matrix.append([False] * len(matrix[0]))
    qr_width = len(matrix[0])
    inner_width = box_width - 2
    qr_left = max(0, (inner_width - qr_width) // 2)
    RESET = '\x1b[0m'
    WHITE_BG = '\x1b[47m'
    BLACK = '\x1b[30m'
    WHITE = '\x1b[97m'

    def left_line(text='', color=''):
        text = str(text)
        if len(text) > inner_width:
            text = text[:max(0, inner_width - 1)] + '…'
        return '│' + color + text.center(inner_width) + RESET
    print()
    print('╭' + '─' * box_width)
    print(left_line(title, accent))
    print('├' + '─' * box_width)
    for y in range(0, len(matrix), 2):
        chars = []
        for x in range(qr_width):
            top = matrix[y][x]
            bottom = matrix[y + 1][x]
            if top and bottom:
                chars.append('█')
            elif top:
                chars.append('▀')
            elif bottom:
                chars.append('▄')
            else:
                chars.append(' ')
        qr_line = ' ' * qr_left + WHITE_BG + BLACK + ''.join(chars) + RESET
        right = max(0, inner_width - qr_left - qr_width)
        qr_line += ' ' * right
        print('│' + qr_line)
    print('├' + '─' * box_width)
    print(left_line(icon + '  ' + title.split(' QR')[0], accent))
    print(left_line(description, WHITE))
    print()
    print('│' + accent + 'INFO:' + RESET + ' ' * max(0, inner_width - 5))
    for item in info_lines:
        txt = '• ' + item
        if len(txt) > inner_width:
            txt = txt[:inner_width - 1] + '…'
        print('│' + WHITE + txt.ljust(inner_width) + RESET)
    print()
    print('│' + accent + 'URL:' + RESET + ' ' * max(0, inner_width - 4))
    url_text = url
    if len(url_text) > inner_width:
        url_text = url_text[:inner_width - 1] + '…'
    print('│' + ('\x1b[96m' + url_text + RESET).center(inner_width + len(RESET) + len('\x1b[96m')))
    print('╰' + '─' * box_width)

def print_terminal_qr(title, url):
    if 'PLAYER' in title.upper():
        _ansi_box(title, url, '\x1b[96m', '🖥', 'Open on the device connected to TV', ['Scan this QR code', 'This device acts as a PLAYER', 'Each Player has its own Player Code', 'Each Player has an independent queue'])
    else:
        _ansi_box(title, url, '\x1b[95m', '📱', 'Open on a phone, tablet or other device', ['Scan this QR code', 'Select the Player you want to control', 'Remote shows CONNECTED [PLAYER CODE]', 'Search, play and add songs to queue'])

def print_startup_ui(player_url, remote_url):
    import shutil
    term_width = shutil.get_terminal_size(fallback=(100, 40)).columns
    RESET = '\x1b[0m'
    CYAN = '\x1b[96m'
    GREEN = '\x1b[92m'
    YELLOW = '\x1b[93m'
    MAGENTA = '\x1b[95m'
    DIM = '\x1b[90m'
    print('\x1b[2J\x1b[H', end='')
    print('╭' + '─' * max(20, term_width - 2) + '╮')
    print('│' + CYAN + '🎤  KARAOKE JUKEBOX'.center(max(20, term_width - 2)) + RESET + '│')
    print('│' + GREEN + 'START SERVER SUCCESSFUL'.center(max(20, term_width - 2)) + RESET + '│')
    print('╰' + '─' * max(20, term_width - 2) + '╯')
    print_terminal_qr('PLAYER QR CODE', player_url)
    print_terminal_qr('REMOTE QR CODE', remote_url)
    inner = max(20, term_width - 4)
    print('╭' + '─' * inner + '╮')
    print('│' + YELLOW + 'QUICK GUIDE'.center(inner) + RESET + '│')
    print('├' + '─' * inner + '┤')
    guide = [('PLAYER', 'Each Player has its own Player Code and independent queue.'), ('REMOTE', 'Scan Remote QR, then select the Player to control.'), ('MULTI-PLAYER', 'Multiple Players can run at the same time.'), ('--zip', 'ZIP STORED; originals are deleted after successful zip.'), ('SERVER', 'Normal HTTP logs are SILENT; important errors remain visible.')]
    for key, val in guide:
        text = f'{key:<13} │ {val}'
        if len(text) > inner:
            text = text[:inner - 1] + '…'
        print('│' + text.ljust(inner) + '│')
    print('╰' + '─' * inner + '╯')
    print()
    status = '●  SERVER RUNNING     │     ●  HTTP LOGS SILENT'
    print('╭' + '─' * inner + '╮')
    print('│' + GREEN + status.center(inner) + RESET + '│')
    print('╰' + '─' * inner + '╯')
    print()

class JukeboxHandler(BaseHTTPRequestHandler):

    def log_message(self, format, *args):
        pass
    server_version = 'KaraokeJukebox/2.0-ZIP-FIXED-QR'
    timeout = 15

    def setup(self):
        super().setup()
        try:
            self.connection.settimeout(30)
        except Exception:
            pass

    def log_message(self, fmt, *args):
        pass

    def send_json(self, data, status=200):
        body = json.dumps(data, ensure_ascii=False, separators=(',', ':')).encode('utf-8')
        self.send_response(status)
        self.send_header('Content-Type', 'application/json; charset=utf-8')
        self.send_header('Content-Length', str(len(body)))
        self.send_header('Cache-Control', 'no-store')
        self.send_header('Connection', 'close')
        self.end_headers()
        try:
            self.wfile.write(body)
        except (BrokenPipeError, ConnectionResetError, socket.timeout):
            pass

    def send_html(self, html):
        body = html.encode('utf-8')
        self.send_response(200)
        self.send_header('Content-Type', 'text/html; charset=utf-8')
        self.send_header('Content-Length', str(len(body)))
        self.send_header('Cache-Control', 'no-store')
        self.send_header('Connection', 'close')
        self.end_headers()
        try:
            self.wfile.write(body)
        except (BrokenPipeError, ConnectionResetError, socket.timeout):
            pass

    def send_svg(self, svg):
        body = svg.encode('utf-8')
        self.send_response(200)
        self.send_header('Content-Type', 'image/svg+xml')
        self.send_header('Content-Length', str(len(body)))
        self.send_header('Cache-Control', 'no-store')
        self.send_header('Connection', 'close')
        self.end_headers()
        try:
            self.wfile.write(body)
        except (BrokenPipeError, ConnectionResetError, socket.timeout):
            pass

    def redirect(self, location):
        self.send_response(302)
        self.send_header('Location', location)
        self.send_header('Cache-Control', 'no-store')
        self.send_header('Connection', 'close')
        self.end_headers()

    def do_GET(self):
        parsed = urllib.parse.urlparse(self.path)
        path = urllib.parse.unquote(parsed.path)
        if path == '/':
            self.redirect('/player')
            return
        if path == '/singleplayer':
            self.send_html(SINGLEPLAYER_HTML)
            return
        if path == '/player':
            self.send_html(PLAYER_CLAIM_HTML)
            return
        if path == '/player-ui':
            token = get_player_token(self)
            if not token:
                token = normalize_player_token(urllib.parse.parse_qs(parsed.query).get('token', [None])[0])
            if not token:
                self.redirect('/player')
                return
            get_player_state(token, True)
            self.send_html(PLAYER_HTML.replace('__JUKEBOX_VERSION__', JUKEBOX_VERSION))
            return
        if path == '/remote':
            remote_token = normalize_player_token(urllib.parse.parse_qs(parsed.query).get('player', [None])[0])
            if not remote_token:
                self.send_html(REMOTE_SELECT_HTML)
            else:
                cleanup_players()
                with players_lock:
                    active = remote_token in players and time.time() - players[remote_token].get('last_seen', 0) <= PLAYER_ACTIVE_WINDOW
                if active:
                    self.send_html(REMOTE_HTML)
                else:
                    self.send_html(REMOTE_SELECT_HTML)
            return
        if path == '/api/qr':
            data = urllib.parse.parse_qs(parsed.query).get('data', [''])[0]
            if not data:
                self.send_response(400)
                self.end_headers()
                return
            qr = qrcode.QRCode(version=None, error_correction=qrcode.constants.ERROR_CORRECT_M, box_size=1, border=4)
            qr.add_data(data)
            qr.make(fit=True)
            matrix = qr.get_matrix()
            size = len(matrix)
            rects = []
            for y, row in enumerate(matrix):
                for x, cell in enumerate(row):
                    if cell:
                        rects.append(f'<rect x="{x}" y="{y}" width="1" height="1"/>')
            svg = f"""<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 {size} {size}" shape-rendering="crispEdges"><rect width="100%" height="100%" fill="white"/><g fill="black">{''.join(rects)}</g></svg>"""
            self.send_svg(svg)
            return
        if path == '/api/internet-status':
            self.send_json({'ok': True, 'online': check_internet_connection()})
            return
        if path == '/api/youtube-search':
            if not check_internet_connection():
                self.send_json({'ok': False, 'offline': True, 'message': 'OFFLINE — YouTube unavailable'}, 503)
                return
            query = urllib.parse.parse_qs(parsed.query).get('q', [''])[0].strip()
            if not query:
                self.send_json({'ok': True, 'results': []})
                return
            try:
                results = youtube_search(query)
                self.send_json({'ok': True, 'results': results})
            except urllib.error.HTTPError as e:
                try:
                    detail = e.read().decode('utf-8', errors='replace')
                except Exception:
                    detail = ''
                self.send_json({'ok': False, 'message': 'YouTube API error', 'detail': detail[:500]}, 502)
            except Exception as e:
                self.send_json({'ok': False, 'message': str(e)}, 500)
            return
        if path == '/api/songs':
            query = urllib.parse.parse_qs(parsed.query)
            try:
                offset = max(0, int(query.get('offset', ['0'])[0]))
            except Exception:
                offset = 0
            try:
                limit = int(query.get('limit', ['50'])[0])
            except Exception:
                limit = 50
            limit = max(1, min(limit, 100))
            search = query.get('search', [''])[0].strip().lower()
            folder = query.get('folder', [''])[0].strip().replace('\\', '/')
            internet_online = check_internet_connection()
            with state_lock:
                source = songs[:]
                index = search_index.copy()
            if folder == SAVED_LINKS_FOLDER:
                source = get_saved_youtube_songs() if internet_online else []
            elif folder:
                source = [song for song in source if song_folder_path(song) == folder]
            if folder == '' and internet_online:
                existing_ids = {song['id'] for song in source}
                for saved_song in get_saved_youtube_songs():
                    if saved_song['id'] not in existing_ids:
                        source.append(saved_song)
                        existing_ids.add(saved_song['id'])
            if search:
                source = [song for song in source if search in index.get(song['id'], search_blob(song))]
            total = len(source)
            page = source[offset:offset + limit]
            has_more = offset + len(page) < total
            with state_lock:
                all_source = songs[:]
            if search:
                if internet_online and folder != SAVED_LINKS_FOLDER:
                    existing_ids = {song['id'] for song in all_source}
                    for saved_song in get_saved_youtube_songs():
                        if saved_song['id'] not in existing_ids:
                            all_source.append(saved_song)
                            existing_ids.add(saved_song['id'])
                all_source = [song for song in all_source if search in index.get(song['id'], search_blob(song))]
            folder_counts = {}
            for song in all_source:
                folder_path = song_folder_path(song)
                if folder_path:
                    folder_counts[folder_path] = folder_counts.get(folder_path, 0) + 1
            saved_count = len(get_saved_youtube_songs()) if internet_online else 0
            if internet_online:
                folder_counts[SAVED_LINKS_FOLDER] = saved_count
            folders = [{'path': path, 'count': count} for path, count in sorted(folder_counts.items(), key=lambda item: item[0].lower())]
            self.send_json({'ok': True, 'count': total, 'offset': offset, 'limit': limit, 'has_more': has_more, 'folders': folders, 'songs': [public_song(song) for song in page], 'internet_online': internet_online})
            return
        if path == '/api/queue':
            with state_lock:
                result = get_queue()
                version = queue_version
            self.send_json({'ok': True, 'version': version, 'queue': result})
            return
        if path == '/api/players':
            cleanup_players()
            now = time.time()
            result = []
            with players_lock:
                for token, state in players.items():
                    if now - state.get('last_seen', 0) <= PLAYER_ACTIVE_WINDOW:
                        result.append({'token': token, 'id': token[:6].upper(), 'last_seen': state.get('last_seen', 0), 'active': True})
            result.sort(key=lambda x: x['id'])
            self.send_json({'ok': True, 'players': result})
            return
        if path == '/api/player':
            token = get_player_token(self)
            state = get_player_state(token, False)
            if state is None:
                self.send_json({'ok': False, 'message': 'Missing player token'}, 400)
                return
            with state_lock:
                current = public_song_by_id(state['current_song_id']) if state['current_song_id'] else None
                result_queue = [public_song_by_id(sid) for sid in state['queue'] if get_song_by_id(sid) is not None]
                playing = state['playing']
                version = state['version']
            self.send_json({'ok': True, 'version': version, 'current': current, 'queue': result_queue, 'playing': playing})
            return
        if path == '/api/player-heartbeat':
            token = get_player_token(self)
            if not token:
                self.send_json({'ok': False, 'message': 'Missing player token'}, 400)
                return
            with players_lock:
                state = players.get(token)
                if state is None:
                    self.send_json({'ok': False, 'player_active': False, 'message': 'Player not found'}, 404)
                    return
                state['last_seen'] = time.time()
            self.send_json({'ok': True, 'player_active': True, 'last_seen': state['last_seen']})
            return
        if path == '/api/player-command':
            token = get_player_token(self)
            state = get_player_state(token, False)
            if state is None:
                self.send_json({'ok': False, 'message': 'Missing player token'}, 400)
                return
            with state_lock:
                cmd = state['command']
                if cmd is not None:
                    cmd = dict(cmd)
                    if isinstance(cmd.get('song'), dict):
                        cmd['song'] = dict(cmd['song'])
            self.send_json({'ok': True, 'command': cmd})
            return
        if path == '/api/connection-status':
            token = get_player_token(self)
            if not token:
                query_token = urllib.parse.parse_qs(urllib.parse.urlparse(self.path).query).get('player', [''])[0]
                token = normalize_player_token(query_token)
            now = time.time()
            with players_lock:
                state = players.get(token) if token else None
                last_seen = state.get('last_seen') if state else None
            age = now - last_seen if last_seen else None
            active = bool(state and age is not None and (age <= PLAYER_ACTIVE_WINDOW))
            self.send_json({'ok': True, 'player_active': active, 'last_seen': last_seen, 'age': round(age, 2) if age is not None else None, 'timeout': PLAYER_ACTIVE_WINDOW})
            return
        if path == '/preview':
            self.serve_preview()
            return
        if path.startswith('/video/'):
            relative = path[len('/video/'):]
            self.serve_video(relative)
            return
        self.send_json({'ok': False, 'error': 'Not found'}, 404)

    def do_POST(self):
        parsed = urllib.parse.urlparse(self.path)
        path = urllib.parse.unquote(parsed.path)
        try:
            length = int(self.headers.get('Content-Length', '0'))
        except Exception:
            length = 0
        if length > 1024 * 1024:
            self.send_json({'ok': False, 'message': 'Request too large'}, 413)
            return
        body = self.rfile.read(length) if length else b''
        try:
            data = json.loads(body.decode('utf-8')) if body else {}
        except Exception:
            data = {}
        if path == '/api/youtube-save-playable':
            if not check_internet_connection():
                self.send_json({'ok': False, 'offline': True, 'message': 'OFFLINE — Saved Links unavailable'}, 503)
                return
            try:
                video_id = str(data.get('youtube_id', '')).strip()
                title = str(data.get('title', '')).strip()
                artist = str(data.get('artist', '')).strip()
                thumbnail = str(data.get('thumbnail', '')).strip()
                saved, message = save_playable_youtube_link(video_id, title, artist, thumbnail)
                self.send_json({'ok': True, 'saved': saved, 'message': message})
            except Exception as e:
                self.send_json({'ok': False, 'message': str(e)}, 500)
            return
        if path == '/api/player/claim':
            token = get_player_token(self)
            if not token:
                self.send_json({'ok': False, 'message': 'Missing Player tab token'}, 400)
                return
            get_player_state(token, True)
            self.send_json({'ok': True, 'player_id': token})
            return
        if path == '/api/player/release':
            token = get_player_token(self)
            if token:
                with players_lock:
                    players.pop(token, None)
            self.send_json({'ok': True})
            return
        if path == '/api/queue/add':
            song_id = data.get('id')
            if not isinstance(song_id, str):
                self.send_json({'ok': False, 'message': 'Invalid song ID'}, 400)
                return
            ok, message = add_to_queue(get_player_token(self), song_id)
            self.send_json({'ok': ok, 'message': message, 'queue': get_queue(get_player_token(self))})
            return
        if path == '/api/queue/remove':
            try:
                position = int(data.get('position'))
            except Exception:
                position = -1
            ok, message = remove_from_queue(get_player_token(self), position)
            self.send_json({'ok': ok, 'message': message, 'queue': get_queue(get_player_token(self))})
            return
        if path == '/api/queue/reorder':
            try:
                from_position = int(data.get('from_position'))
                to_position = int(data.get('to_position'))
            except Exception:
                from_position = -1
                to_position = -1
            ok, message = reorder_queue(get_player_token(self), from_position, to_position)
            self.send_json({'ok': ok, 'message': message, 'queue': get_queue(get_player_token(self))})
            return
        if path == '/api/queue/clear':
            clear_queue(get_player_token(self))
            self.send_json({'ok': True, 'message': 'Queue cleared'})
            return
        if path == '/api/player/next':
            next_song = start_next_song(get_player_token(self))
            if next_song is None:
                self.send_json({'ok': False, 'message': 'Queue is empty', 'current': None, 'queue': get_queue(get_player_token(self))})
                return
            self.send_json({'ok': True, 'current': next_song, 'queue': get_queue(get_player_token(self))})
            return
        if path == '/api/player/previous':
            previous_song = start_previous_song(get_player_token(self))
            if previous_song is None:
                self.send_json({'ok': False, 'message': 'No previous song'})
                return
            self.send_json({'ok': True, 'current': previous_song, 'queue': get_queue(get_player_token(self))})
            return
        if path == '/api/player/toggle':
            playing = toggle_playing(get_player_token(self))
            self.send_json({'ok': True, 'playing': playing})
            return
        if path == '/api/player/set-playing':
            value = data.get('playing')
            if not isinstance(value, bool):
                self.send_json({'ok': False, 'message': 'Invalid playing value'}, 400)
                return
            playing = set_playing(get_player_token(self), value)
            self.send_json({'ok': True, 'playing': playing})
            return
        if path == '/api/player/play':
            song_id = data.get('id')
            if not isinstance(song_id, str):
                self.send_json({'ok': False, 'message': 'Invalid song ID'}, 400)
                return
            if not set_current_song(get_player_token(self), song_id):
                if song_id.startswith('yt:') and len(song_id) > 3:
                    yt_video_id = song_id[3:].strip()
                    if re.fullmatch('[A-Za-z0-9_-]{6,20}', yt_video_id):
                        with youtube_cache_lock:
                            fallback_song = {'id': song_id, 'code': 'YT', 'title': 'YouTube', 'artist': '', 'filename': 'YouTube', 'path': '@YOUTUBE@/' + yt_video_id, 'youtube': True, 'youtube_id': yt_video_id, 'thumbnail': ''}
                            youtube_songs[song_id] = fallback_song
                        if set_current_song(get_player_token(self), song_id):
                            self.send_json({'ok': True, 'current': get_current_song(get_player_token(self))})
                            return
                self.send_json({'ok': False, 'message': 'Song not found: ' + song_id}, 404)
                return
            self.send_json({'ok': True, 'current': get_current_song(get_player_token(self))})
            return
        self.send_json({'ok': False, 'message': 'Unknown endpoint'}, 404)

    def serve_preview(self):
        if not os.path.isfile(PREVIEW_IMAGE):
            self.send_error(404, 'Preview image not found')
            return
        try:
            file_size = os.path.getsize(PREVIEW_IMAGE)
            content_type = mimetypes.guess_type(PREVIEW_IMAGE)[0] or 'image/png'
            self.send_response(200)
            self.send_header('Content-Type', content_type)
            self.send_header('Content-Length', str(file_size))
            self.send_header('Cache-Control', 'public, max-age=60')
            self.send_header('Connection', 'close')
            self.end_headers()
            self.copy_file(PREVIEW_IMAGE, 0, file_size)
        except OSError:
            self.send_error(404, 'Preview unavailable')

    def serve_video(self, relative_path):
        relative_path = relative_path.replace('\\', '/')
        relative_path = relative_path.lstrip('/')
        base = os.path.abspath(KARAOKE_DIR)
        requested = os.path.abspath(os.path.join(KARAOKE_DIR, relative_path))
        if not (requested == base or requested.startswith(base + os.sep)):
            self.send_error(403, 'Forbidden')
            return
        if relative_path.startswith('@ZIP@/') and '::' in relative_path:
            zip_rel, entry_name = relative_path[6:].split('::', 1)
            zip_path = os.path.abspath(os.path.join(KARAOKE_DIR, zip_rel))
            if not (zip_path == base or zip_path.startswith(base + os.sep)):
                self.send_error(403, 'Forbidden')
                return
            self.serve_zip_video(zip_path, entry_name)
            return
        if not os.path.isfile(requested):
            self.send_error(404, 'Video not found')
            return
        try:
            file_size = os.path.getsize(requested)
        except OSError:
            self.send_error(404, 'File unavailable')
            return
        content_type = mimetypes.guess_type(requested)[0] or 'video/mp4'
        range_header = self.headers.get('Range')
        if not range_header:
            self.send_response(200)
            self.send_header('Content-Type', content_type)
            self.send_header('Content-Length', str(file_size))
            self.send_header('Accept-Ranges', 'bytes')
            self.send_header('Cache-Control', 'no-cache')
            self.send_header('Connection', 'close')
            self.end_headers()
            self.copy_file(requested, 0, file_size)
            return
        try:
            if not range_header.startswith('bytes='):
                raise ValueError
            range_value = range_header.split('=', 1)[1]
            range_value = range_value.split(',', 1)[0]
            start_text, end_text = range_value.split('-', 1)
            if start_text:
                start = int(start_text)
            else:
                suffix = int(end_text)
                if suffix <= 0:
                    raise ValueError
                start = max(file_size - suffix, 0)
            if end_text:
                end = int(end_text)
            else:
                end = file_size - 1
            if start < 0 or start >= file_size or end < start:
                raise ValueError
            end = min(end, file_size - 1)
        except Exception:
            self.send_response(416)
            self.send_header('Content-Range', 'bytes */' + str(file_size))
            self.send_header('Connection', 'close')
            self.end_headers()
            return
        length = end - start + 1
        self.send_response(206)
        self.send_header('Content-Type', content_type)
        self.send_header('Content-Length', str(length))
        self.send_header('Content-Range', 'bytes ' + str(start) + '-' + str(end) + '/' + str(file_size))
        self.send_header('Accept-Ranges', 'bytes')
        self.send_header('Cache-Control', 'no-cache')
        self.send_header('Connection', 'close')
        self.end_headers()
        self.copy_file(requested, start, length)

    def serve_zip_video(self, zip_path, entry_name):
        try:
            with zipfile.ZipFile(zip_path, 'r') as zf:
                try:
                    info = zf.getinfo(entry_name)
                except KeyError:
                    self.send_error(404, 'Video not found in ZIP')
                    return
                if info.is_dir():
                    self.send_error(404, 'Video not found')
                    return
                file_size = info.file_size
                content_type = mimetypes.guess_type(entry_name)[0] or 'video/mp4'
                range_header = self.headers.get('Range')
                if not range_header:
                    self.send_response(200)
                    self.send_header('Content-Type', content_type)
                    self.send_header('Content-Length', str(file_size))
                    self.send_header('Accept-Ranges', 'bytes')
                    self.send_header('Cache-Control', 'no-cache')
                    self.send_header('Connection', 'close')
                    self.end_headers()
                    self.copy_zip_file(zf, info, 0, file_size)
                    return
                try:
                    if not range_header.startswith('bytes='):
                        raise ValueError
                    range_value = range_header.split('=', 1)[1].split(',', 1)[0]
                    start_text, end_text = range_value.split('-', 1)
                    if start_text:
                        start = int(start_text)
                    else:
                        suffix = int(end_text)
                        if suffix <= 0:
                            raise ValueError
                        start = max(file_size - suffix, 0)
                    if end_text:
                        end = int(end_text)
                    else:
                        end = file_size - 1
                    if start < 0 or start >= file_size or end < start:
                        raise ValueError
                    end = min(end, file_size - 1)
                except Exception:
                    self.send_response(416)
                    self.send_header('Content-Range', 'bytes */' + str(file_size))
                    self.send_header('Connection', 'close')
                    self.end_headers()
                    return
                length = end - start + 1
                self.send_response(206)
                self.send_header('Content-Type', content_type)
                self.send_header('Content-Length', str(length))
                self.send_header('Content-Range', 'bytes ' + str(start) + '-' + str(end) + '/' + str(file_size))
                self.send_header('Accept-Ranges', 'bytes')
                self.send_header('Cache-Control', 'no-cache')
                self.send_header('Connection', 'close')
                self.end_headers()
                self.copy_zip_file(zf, info, start, length)
        except (OSError, zipfile.BadZipFile, KeyError):
            try:
                self.send_error(404, 'ZIP video unavailable')
            except Exception:
                pass

    def copy_zip_file(self, zf, info, start, length):
        try:
            with zf.open(info, 'r') as file:
                remaining_skip = start
                while remaining_skip > 0:
                    chunk = file.read(min(1024 * 1024, remaining_skip))
                    if not chunk:
                        return
                    remaining_skip -= len(chunk)
                remaining = length
                while remaining > 0:
                    chunk = file.read(min(1024 * 1024, remaining))
                    if not chunk:
                        break
                    self.wfile.write(chunk)
                    remaining -= len(chunk)
        except (BrokenPipeError, ConnectionResetError, socket.timeout, OSError, zipfile.BadZipFile):
            pass

    def copy_file(self, path, start, length):
        try:
            with open(path, 'rb') as file:
                file.seek(start)
                remaining = length
                while remaining > 0:
                    chunk = file.read(min(1024 * 1024, remaining))
                    if not chunk:
                        break
                    self.wfile.write(chunk)
                    remaining -= len(chunk)
        except (BrokenPipeError, ConnectionResetError, socket.timeout, OSError):
            pass

def get_local_ip():
    sock = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
    try:
        sock.connect(('8.8.8.8', 80))
        return sock.getsockname()[0]
    except Exception:
        try:
            return socket.gethostbyname(socket.gethostname())
        except Exception:
            return '127.0.0.1'
    finally:
        sock.close()

def open_browser(url):
    try:
        subprocess.Popen(['termux-open-url', url], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
        return True
    except Exception as e:
        print('BROWSER OPEN ERROR:', e)
        return False

def create_karaoke_zip():
    os.makedirs(KARAOKE_DIR, exist_ok=True)
    output_path = os.path.join(KARAOKE_DIR, 'MY KARAOKE.zip')
    temp_path = output_path + '.part'
    print()
    print('==========================================')
    print('   KARAOKE JUKEBOX v8.5 -- ZIP MOVE')
    print('==========================================')
    print('Source:', KARAOKE_DIR)
    print('Output:', output_path)
    print('Mode: ZIP STORED (-0) + MOVE/DELETE')
    print()
    videos = []
    for root, dirs, files in os.walk(KARAOKE_DIR):
        dirs[:] = sorted((d for d in dirs if not d.startswith('.')))
        for name in sorted(files, key=str.lower):
            if name.startswith('.'):
                continue
            if os.path.splitext(name)[1].lower() not in VIDEO_EXTENSIONS:
                continue
            full_path = os.path.join(root, name)
            rel_path = os.path.relpath(full_path, KARAOKE_DIR).replace('\\', '/')
            videos.append((full_path, rel_path))
    if not videos:
        if os.path.isfile(output_path):
            print('No loose video files found.')
            print('Existing archive:', output_path)
            return 0
        print('No video files found in KARAOKE folder.')
        return 1
    if os.path.exists(temp_path):
        try:
            os.remove(temp_path)
        except OSError as e:
            print('ERROR: Cannot remove old temporary ZIP:', e)
            return 1
    if os.path.exists(output_path):
        print('ERROR: MY KARAOKE.zip already exists.')
        print('For safety, it was NOT overwritten.')
        print('Rename/remove the old ZIP first, then run --zip again.')
        return 1
    print('Videos found:', len(videos))
    print('IMPORTANT: Original video is deleted after each successful ZIP write.')
    print()
    moved = 0
    try:
        with zipfile.ZipFile(temp_path, mode='w', compression=zipfile.ZIP_STORED, allowZip64=True) as zf:
            for number, (full_path, rel_path) in enumerate(videos, 1):
                source_size = os.path.getsize(full_path)
                print('[{}/{}] {}'.format(number, len(videos), rel_path), flush=True)
                zf.write(full_path, arcname=rel_path, compress_type=zipfile.ZIP_STORED)
                info = zf.getinfo(rel_path)
                if info.file_size != source_size or info.compress_type != zipfile.ZIP_STORED:
                    raise RuntimeError('ZIP verification failed for: ' + rel_path)
                os.remove(full_path)
                moved += 1
                print('        moved -> ZIP, original deleted', flush=True)
        os.replace(temp_path, output_path)
    except Exception as e:
        print()
        print('ZIP/MOVE ERROR:', e)
        print('Moved before error:', moved, 'of', len(videos))
        if os.path.exists(temp_path):
            print('Partial archive kept for recovery:', temp_path)
        print('Files already moved were not duplicated back to save storage.')
        return 1
    for root, dirs, files in os.walk(KARAOKE_DIR, topdown=False):
        if os.path.abspath(root) == os.path.abspath(KARAOKE_DIR):
            continue
        try:
            if not os.listdir(root):
                os.rmdir(root)
        except OSError:
            pass
    size = os.path.getsize(output_path)
    print()
    print('ZIP MOVE COMPLETED SUCCESSFULLY')
    print('File:', output_path)
    print('Size: {:.2f} GB ({:,} bytes)'.format(size / 1024 ** 3, size))
    print('Videos moved/deleted:', moved)
    print('Original loose videos remaining: 0')
    print()
    return 0

def main():
    if '--generate' in __import__('sys').argv[1:]:
        generate_jukebox_key()
        return
    if not require_jukebox_key():
        return
    print()
    print('==========================================')
    print(f'       KARAOKE JUKEBOX SERVER v{JUKEBOX_VERSION}')
    print('==========================================')
    print()
    print('KARAOKE FOLDER:')
    print(KARAOKE_DIR)
    print()
    os.makedirs(KARAOKE_DIR, exist_ok=True)
    print('Scanning karaoke files...')
    scan_songs()
    print('Songs found:', len(songs))
    print()
    scanner = threading.Thread(target=scanner_loop, daemon=True, name='SongScanner')
    scanner.start()
    server = JukeboxHTTPServer((HOST, PORT), JukeboxHandler)
    local_ip = get_local_ip()
    player_url = 'http://' + local_ip + ':' + str(PORT) + '/player'
    remote_url = 'http://' + local_ip + ':' + str(PORT) + '/remote'
    print('Server running...')
    print()
    print_startup_ui(player_url, remote_url)
    try:
        server.serve_forever()
    except KeyboardInterrupt:
        print()
        print('Stopping server...')
    finally:
        server.server_close()
if __name__ == '__main__':
    if '--zip' in __import__('sys').argv[1:]:
        raise SystemExit(create_karaoke_zip())
    main()
